#schoolView .sch-words{font-size:12.5px;color:#8a8aa0}
#schoolView .sch-batch-h{font-size:14px;margin:0 0 6px;color:#1f4e79}
#schoolView .sch-bank{width:100%;border-collapse:collapse;font-size:13px}
#schoolView .sch-bank th,#schoolView .sch-bank td{border:1px solid #e2ebf4;padding:5px 7px;text-align:left;vertical-align:top}
#schoolView .sch-bank th{background:#f2f7fc;font-weight:600;white-space:nowrap}
