assert '</script' not in _cloud_sdk.lower() and '<!--' not in _cloud_sdk, 'SDK 含危險字串，不可內聯'
assert 'endpoint' in _cloud_cfg and 'publishableKey' in _cloud_cfg, '雲配置缺欄位'
_kb_json = _ai_kb.kb_json(TEMPLATE)
assert len(_kb_json) > 1000, '知識庫抽取失敗'
# 知識庫不得混入 Band 分檔或學費金額（葉工硬前提：掐掉編 Band 的源頭）
